import imageCompression from "browser-image-compression";
import { CloseTips, ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo } from "@/util/tips.ts";
import type { GlobalProperties } from "@/util/tips.ts";
import { GetText } from "@/text/library.ts";
export type UploadImageCallbackUrl = {
  url: string;
  alt: string;
  title: string;
};

export type UploadImageTokenResponse = {
  code: number;
  data: {
    upload_url: string;
    preview_url: string;
  };
};

// 压缩参数：所有图片都压缩并转为 webp，GIF 透传避免丢失动画
const IMAGE_COMPRESS_OPTIONS = {
  maxSizeMB: 2,
  maxWidthOrHeight: 1920,
  useWebWorker: true,
  initialQuality: 0.8,
  fileType: "image/webp" as const,
};

// 压缩单张图片：GIF 直接返回原文件，其他格式转为 webp
export async function CompressImage(file: File): Promise<File> {
  if (file.type === "image/gif") {
    return file;
  }
  try {
    const compressed = await imageCompression(file, IMAGE_COMPRESS_OPTIONS);
    // 压缩后若反而变大，则使用原文件
    return compressed.size < file.size ? compressed : file;
  } catch {
    return file;
  }
}

export function PostR2Image(uploadUrl: string, image: File) {
  return fetch(uploadUrl, {
    method: "PUT",
    headers: {
      "Content-Type": image.type,
    },
    body: image,
  });
}

export async function HandleR2ImageUpload(
  files: File[],
  callback: (urls: UploadImageCallbackUrl[]) => void,
  globalProperties: GlobalProperties,
  getTokenHandler: () => Promise<UploadImageTokenResponse>
) {
  let urls = [] as { url: string; alt: string; title: string }[];

  const loadingMessage = ShowTextTipsInfo(globalProperties, "图片正在上传，请稍候...", 0);

  try {
    for (const file of files) {
      const res = await getTokenHandler();
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        const [_, text] = GetText(res.code);
        urls = urls.concat({
          url: text,
          alt: "上传失败",
          title: "",
        });
        continue;
      }
      const uploadUrl = res.data.upload_url;
      // 上传前压缩图片
      const imageToUpload = await CompressImage(file);
      await PostR2Image(uploadUrl, imageToUpload);
      urls = urls.concat({
        url: res.data.preview_url,
        alt: file.name,
        title: file.name,
      });
    }
  } catch (error) {
    ShowTextTipsError(globalProperties, "上传失败");
    urls = urls.concat({
      url: "上传失败",
      alt: "上传失败",
      title: "",
    });
  } finally {
    callback(urls);
    await CloseTips(globalProperties, loadingMessage);
  }
}
